<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Builder; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\SoftDeletes;
class EvaluacionFisica extends Model { use SoftDeletes; protected $table='evaluaciones_fisicas'; protected $fillable=['cliente_id','evaluador_id','evaluada_at','metodo','observaciones','creada_por']; protected function casts(): array { return ['evaluada_at'=>'datetime']; } public function scopeEntreFechas(Builder $query,$desde,$hasta): Builder { return $query->whereBetween('evaluada_at',[$desde,$hasta]); } public function cliente(): BelongsTo { return $this->belongsTo(Cliente::class); } public function evaluador(): BelongsTo { return $this->belongsTo(Personal::class,'evaluador_id'); } public function creadaPor(): BelongsTo { return $this->belongsTo(User::class,'creada_por'); } public function detalles(): HasMany { return $this->hasMany(DetalleEvaluacion::class); } public function medida(string $codigo): ?DetalleEvaluacion { return $this->detalles->first(fn($detalle)=>$detalle->tipoMedida?->codigo===$codigo); } }
